INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f25f5cfb-650e-4e94-b125-953c48d45608', '21feff02-016d-46e2-bb9d-c27495133b1b', '121. óra: Kördiagram', 'Kördiagram értelmezése, körcikkek szöge, százalékos megoszlás.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "48b16b8d-f5ad-48c5-ae59-e1f526874acd", "text": "Mire szolgál a kördiagram?", "type": "multiple-choice", "options": [{"id": "bfa7f570-11bd-4e10-9914-321c643b6836", "text": "Az egyes részek teljes egészhez (100%) viszonyított arányának szemléltetésére", "isCorrect": true}, {"id": "337b8c04-22a1-4478-b6e3-ddc4eafe5f57", "text": "Vonalak összekötésére", "isCorrect": false}, {"id": "6b7c2049-372c-4ced-b3e6-fc0ab7ddb302", "text": "Pontok rajzolására", "isCorrect": false}, {"id": "930ad713-2e2c-4ad0-9991-ba31f0d715b5", "text": "Időbeli növekedés ábrázolására", "isCorrect": false}], "timeLimit": 15}, {"id": "dd33a568-363b-4e3e-aade-4e5339c91b8f", "text": "Hány fokos a kördiagram teljes köre (100%)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "17513f93-50e7-44ad-81a0-1246a07a8317", "text": "Hány fokos körcikk tartozik az 50%-os (fél) részhez? (360 / 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "248380ad-f465-4cb4-96d6-b6852be161f8", "text": "Hány fokos körcikk tartozik a 25%-os (negyed) részhez? (360 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "736fc6cf-9a8f-4027-9379-712e7da7422d", "text": "Hány fokos körcikk tartozik a 10%-os részhez? (360 / 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "912d5e4a-f894-4b0e-a9a4-b274ece4d2b2", "text": "A kördiagramon a körcikkek középponti szögei egyenesen arányosak a képviselt százalékkal.", "type": "true-false", "options": [{"id": "98615b2c-6243-42f3-ae48-9e393168d83b", "text": "Igaz", "isCorrect": true}, {"id": "3fe4bf92-6bec-4a13-9772-988bace075d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5140a1d0-881c-4f59-9a76-37b227262e11", "text": "A körcikkek szögeinek összege mindig 360°.", "type": "true-false", "options": [{"id": "a9758901-f2d7-4120-b8b6-c95fc58e4304", "text": "Igaz", "isCorrect": true}, {"id": "f4ee6177-24ea-4cc3-be4e-fbe2c010e3fc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c06b266f-a701-41df-8a61-93238c30b763', '21feff02-016d-46e2-bb9d-c27495133b1b', '122. óra: Adatok ábrázolása, átlag', 'Számtani közép (átlag) kiszámítása és ábrázolás digitális eszközzel.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "9c043b0c-2402-4962-bd3f-f03538a5ab51", "text": "Hogyan számítjuk ki több szám számtani középértékét (átlagát)?", "type": "multiple-choice", "options": [{"id": "33af20ad-be08-480c-a22a-5d62c2be7453", "text": "Összeadjuk az adatokat, majd az összeget elosztjuk az adatok darabszámával", "isCorrect": true}, {"id": "5b347e02-1377-482d-99b3-874e7c69e1b5", "text": "Megszorozzuk az adatokat", "isCorrect": false}, {"id": "9cac24f3-7dbd-490d-ae25-ea23d2ebcfb9", "text": "Kivonjuk a legkisebbet a legnagyobból", "isCorrect": false}, {"id": "2c4ed209-7c89-4a05-9743-77e5d43d0ede", "text": "Kiválasztjuk a leggyakoribb számot", "isCorrect": false}], "timeLimit": 15}, {"id": "a595067c-df7c-4837-b83d-1daa7fa7e34a", "text": "Mennyi a 4, 6, 8, 10 számok átlaga? (28 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "1b835796-220a-43c9-be48-7511ea4c62f6", "text": "Mennyi a 10, 20, 30, 40, 50 számok átlaga? (150 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "06bab140-761d-41db-a338-87591b14ac78", "text": "Egy diák osztályzatai: 5, 4, 5, 5, 3. Mennyi a tanulmányi átlaga? (22 / 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4.4"}, {"id": "b0af01ff-2ce0-4dd7-98d3-2f1e7ab25ed4", "text": "Az átlag értéke mindig a legkisebb és a legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "9926ae58-9b52-4810-859a-dc38ce315bce", "text": "Igaz", "isCorrect": true}, {"id": "9c8374de-73f1-4b93-b50d-619416b78a78", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a567b76e-5cae-4609-8ac2-e4d441cc7575", "text": "Digitális táblázatkezelőben (pl. Excel) az ÁTLAG (AVERAGE) függvény azonnal kiszámolja az átlagot.", "type": "true-false", "options": [{"id": "a21cbb9a-9c48-4eed-a4d6-6d0e54418e70", "text": "Igaz", "isCorrect": true}, {"id": "5504da47-21b0-4c66-97eb-2dbb968637d3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "eb3701b4-9efb-488f-890a-1991b9ad62df", "text": "Mennyi a 15 és 25 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e7723a3c-2e00-4c9e-bc1d-079b93ba0f31', '21feff02-016d-46e2-bb9d-c27495133b1b', '123. óra: Dobáljunk kockákat!', 'Kísérletezés dobókockával, gyakoriság, relatív gyakoriság és valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "410e3dc4-ff7b-446f-8005-40a12aa3718c", "text": "Egy szabályos 6 oldalú dobókockával mekkora az esélye a 6-os dobásnak?", "type": "multiple-choice", "options": [{"id": "89eea2fb-2fa0-42d5-a66b-b22bc70de08f", "text": "1 a 6-ból (1/6)", "isCorrect": true}, {"id": "67b97cfb-6078-4836-848e-3746a044b0c1", "text": "1 a 2-ből", "isCorrect": false}, {"id": "a470ccdd-6f21-4525-abf9-b8c358a617c2", "text": "100%", "isCorrect": false}, {"id": "2cd84a05-dd86-4dc3-9dbf-35a4b2339dec", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "162baf87-a922-4abf-b3a9-6825ffaf3a29", "text": "Mennyi a páros szám (2, 4, 6) dobásának valószínűsége dobókockával?", "type": "multiple-choice", "options": [{"id": "d90aa929-ad18-44e3-8253-d73788b5da6e", "text": "3 a 6-ból (3/6 = 1/2 azaz 50%)", "isCorrect": true}, {"id": "2d1167ef-7d6a-4e4c-a1ce-2c88c83a642f", "text": "1/6", "isCorrect": false}, {"id": "d7e64d75-e292-4ae2-9a6b-3a5f97dc35fd", "text": "2/6", "isCorrect": false}, {"id": "fa170939-f4cb-4fae-af03-a28918f77a07", "text": "100%", "isCorrect": false}], "timeLimit": 15}, {"id": "ec2310e2-005e-4886-864d-e7beffaacf2a", "text": "Sok dobási kísérlet végrehajtásakor a relatív gyakoriság megközelíti az elméleti valószínűséget.", "type": "true-false", "options": [{"id": "d5314015-9880-4583-8905-8b41ca138e03", "text": "Igaz", "isCorrect": true}, {"id": "c4414557-e331-4a1c-87e5-bb7dea3553a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0fff3cd8-d5e8-49ce-bd29-3a6b1b5a559c", "text": "Milyen esemény egy kockával 7-est dobni?", "type": "multiple-choice", "options": [{"id": "422676c2-642a-459c-8c29-50d258715559", "text": "Lehetetlen esemény (0%)", "isCorrect": true}, {"id": "0c27079d-7717-45ac-96b7-83d46bb303c3", "text": "Biztos esemény", "isCorrect": false}, {"id": "8b3920ba-a017-4f3c-a687-d8abf9edc4bf", "text": "Lehetséges", "isCorrect": false}, {"id": "3f08aacd-9fb5-4367-b0ca-18f6609cb764", "text": "Véletlen", "isCorrect": false}], "timeLimit": 15}, {"id": "bdfe2e47-ae07-49f2-8ada-1af7c8ad209b", "text": "Milyen esemény egy kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "4db3f783-c602-4eee-a10e-99448a3abcd2", "text": "Biztos esemény (100%)", "isCorrect": true}, {"id": "53fbfb58-1436-4420-9362-92074a1075cc", "text": "Lehetetlen", "isCorrect": false}, {"id": "fcf6dfd0-60e1-49d5-ab99-2debd20ce2d2", "text": "Kétes", "isCorrect": false}, {"id": "326b3a56-6c7c-4b14-bff5-ca7e7345592e", "text": "Ritka", "isCorrect": false}], "timeLimit": 15}, {"id": "65cb9c94-77c0-4bb1-a20e-6ccfe8621d7c", "text": "Hányféle kimenetele lehet két kocka dobásakor a kapott összegeknek? (2-től 12-ig: 11-féle)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "11"}, {"id": "f6b9248c-431c-4afb-a02b-3fa3b5e8040e", "text": "Két kockával a leggyakoribb dobási összeg a 7.", "type": "true-false", "options": [{"id": "b9c61197-8d46-402c-b398-b716733074c7", "text": "Igaz", "isCorrect": true}, {"id": "69feb5a0-af13-4b5f-b118-a6d0673485e8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fa3f775a-3b3d-499c-8a49-3144df6a58f3', '21feff02-016d-46e2-bb9d-c27495133b1b', '124. óra: Dobáljunk pénzérmét!', 'Kísérletezés érmével, fej vagy írás, tapasztalati valószínűség.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "27dae11a-96c0-491b-9d13-976ae8d346b3", "text": "Egy szabályos pénzérme feldobásakor mekkora a fej dobás valószínűsége?", "type": "multiple-choice", "options": [{"id": "f1fd04e6-9cdf-45b3-9b1b-254cdf4495e3", "text": "1 a 2-ből (1/2 azaz 50%)", "isCorrect": true}, {"id": "d661c093-f8cf-4460-84b2-ec7f01e27ce3", "text": "1/4", "isCorrect": false}, {"id": "c272935a-2667-41b8-8426-9ea2d908a57e", "text": "100%", "isCorrect": false}, {"id": "9d0fb77c-9bc7-46eb-ba47-d4ba5c2c5d1c", "text": "0%", "isCorrect": false}], "timeLimit": 15}, {"id": "cdb7e243-a3d6-4c8c-9580-aab4c11e0a95", "text": "Ha 100-szor dobunk fel egy érmét, a fej dobások száma kb. 50 körül várható.", "type": "true-false", "options": [{"id": "552168d6-37b8-423e-9e51-fdba24e84185", "text": "Igaz", "isCorrect": true}, {"id": "017bc3c6-03e0-4828-81a4-3bed0e19ab12", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fb06dc29-5c19-4cb0-8756-e5beced50ffa", "text": "Hány kimenetele lehet 2 érme egyidejű feldobásának? (FF, FI, IF, II)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "0e167916-a628-43a2-a080-85b8d6e2e5cf", "text": "Mekkora a valószínűsége annak, hogy 2 érmével mindkettő fej lesz? (1 a 4-ből = 25%)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "7be5012a-8e7b-4a0f-851a-5b6a0af2dc2a", "text": "A véletlen kísérletek eredményét az egyes próbálkozásoknál nem lehet pontosan kiszámítani, de nagy számnál szabályszerűség mutatkozik.", "type": "true-false", "options": [{"id": "ec4ea035-9897-453e-a096-217b0e187a32", "text": "Igaz", "isCorrect": true}, {"id": "7f04dedf-a24d-4b11-8c0d-bc37f6fd05da", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "edfa1c6c-ba96-428a-9014-e9b24cf05865", "text": "A biztos esemény valószínűsége 100% (vagy 1).", "type": "true-false", "options": [{"id": "701bf611-fbaa-4b3d-9c52-acc8e2fcee8e", "text": "Igaz", "isCorrect": true}, {"id": "f1953305-5990-48b5-aa94-81ab9a926f61", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "100f7497-fb6e-4ec1-8cf0-d0daa57a9341", "text": "A lehetetlen esemény valószínűsége 0% (vagy 0).", "type": "true-false", "options": [{"id": "aaf31b19-9f21-473d-ade3-faa04a689a57", "text": "Igaz", "isCorrect": true}, {"id": "109c96f9-50bc-4f56-b487-4c0e1168b883", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('879aaa3a-8bee-450f-8ef0-40b114cbfacf', '21feff02-016d-46e2-bb9d-c27495133b1b', '125. óra: Összefoglalás', 'Statisztikai és valószínűségi ismeretek összefoglalása.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "1c1aee93-4481-43cb-828e-6bf00abec353", "text": "Mennyi a 6, 8, 10, 12 számok átlaga? (36 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "9"}, {"id": "a9f19679-813e-49cc-b848-8d2a158e2c40", "text": "Hány fokos körcikk felel meg a kördiagramon a 50%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "180"}, {"id": "eb48c135-b72a-447c-bbc0-1474f76323fa", "text": "Hány fokos körcikk felel meg a kördiagramon a 25%-nak?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "b6b389ef-136a-4e27-8128-bdc579d775b9", "text": "Egy kockával 6-ost dobni 1/6 valószínűségű esemény.", "type": "true-false", "options": [{"id": "0c0c0876-6e64-4836-bb93-2093e646fa64", "text": "Igaz", "isCorrect": true}, {"id": "930cc9d2-75ae-428e-b9cb-9e013050efc0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "355b4ab0-260f-4625-a0ae-b9d37097eb74", "text": "Az adatok átlagához az összes adat összegét elosztjuk a darabszámmal.", "type": "true-false", "options": [{"id": "c7853595-85bf-4661-be92-ae2f2bb060ee", "text": "Igaz", "isCorrect": true}, {"id": "5514dde3-a425-42a0-8b1c-836f6de3e4ef", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cdc958b8-c86e-43b1-ae6d-d04458332e9e", "text": "Melyik grafikon alkalmas időbeli változás ábrázolására?", "type": "multiple-choice", "options": [{"id": "2ddef1bd-e6e4-4d06-926c-fd2b1b803083", "text": "Vonaldiagram", "isCorrect": true}, {"id": "d3ffefcc-a201-48a4-a598-26b73df36051", "text": "Kördiagram", "isCorrect": false}, {"id": "84f07494-cedf-4b6d-8e28-815f78ad57ef", "text": "Pontdiagram", "isCorrect": false}, {"id": "6f6ba990-3420-4f45-83fd-6c60a5513ee7", "text": "Képrejtvény", "isCorrect": false}], "timeLimit": 15}, {"id": "9cb942f6-53bb-4c0b-a081-cd2fb943c528", "text": "Mennyi a 20 és 40 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e8027809-49f4-4c27-82e1-6205a00d759a', '21feff02-016d-46e2-bb9d-c27495133b1b', '126. óra: Számonkérés', 'Számonkérés projektmunka és teszt formájában a Statisztikából (10 kérdés).', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "6025c396-98f4-494c-9f5a-8d40b5a67013", "text": "1. Mennyi a 10, 20, 30 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "e2d64d4c-bb4c-426a-8286-0a71034a22b7", "text": "2. Mennyi a 2, 4, 6, 8, 10 számok átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1b7f733f-fac2-43b7-bec8-2c3a212c733e", "text": "3. Hány fokos a teljes kör a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "360"}, {"id": "3fd78eb5-9120-4a4a-8861-86321ed733dd", "text": "4. Hány fokos körcikk jelöli a 10%-ot a kördiagramon?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "5d56e16d-d095-49dc-a3d5-03f6e9294bcc", "text": "5. Mekkora a fej dobás valószínűsége százalékban egy szabályos érmével?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "50"}, {"id": "c3812b60-2957-4007-982a-a7221492e9d9", "text": "6. Milyen esemény egy 6 oldalú kockával 8-ast dobni?", "type": "multiple-choice", "options": [{"id": "7a212d4c-2593-49de-ab25-39c8be671efb", "text": "Lehetetlen esemény", "isCorrect": true}, {"id": "99c7375c-852b-475a-9633-959d5ab41835", "text": "Biztos esemény", "isCorrect": false}, {"id": "f372e01c-fac4-4693-941b-c48912c9826a", "text": "Lehetséges", "isCorrect": false}, {"id": "c01c4895-9a87-4199-8029-ab7f8c39eadd", "text": "Döntetlen", "isCorrect": false}], "timeLimit": 15}, {"id": "d6787745-3872-4476-8cb9-09ffdbfd6dc5", "text": "7. Milyen esemény egy 6 oldalú kockával 1 és 6 közötti számot dobni?", "type": "multiple-choice", "options": [{"id": "66b15059-e232-45ca-989a-33d98ac6d212", "text": "Biztos esemény", "isCorrect": true}, {"id": "2420aa53-c22a-4755-957d-7abe60744d23", "text": "Lehetetlen esemény", "isCorrect": false}, {"id": "edd62c13-0a95-4e0d-a991-39730eef9d63", "text": "Ritka", "isCorrect": false}, {"id": "dcfb1b4c-aaae-43a1-869f-7a080a5febf4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "39af172a-5ebe-4456-b29f-f0df897fa557", "text": "8. Az adatok átlaga mindig a legkisebb és legnagyobb adat közé esik.", "type": "true-false", "options": [{"id": "2fd77ebb-b0e5-4799-8263-8b4fc2444b59", "text": "Igaz", "isCorrect": true}, {"id": "81d267ac-5e71-4562-a674-673c778d6886", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e54fbf80-f5c5-4e46-8d54-cdaf3d9e4dcf", "text": "9. Hány kimenetele lehet 2 érme feldobásának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "b2f6e538-a6ed-4cb2-8e3e-b184fb2da511", "text": "10. A vonaldiagram az adatok időbeli alakulását mutatja meg jól.", "type": "true-false", "options": [{"id": "62955355-4a5f-42be-aacf-3dd41b1fea5f", "text": "Igaz", "isCorrect": true}, {"id": "5ada3039-c3ac-49b1-a4c8-f2cf287509bc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3fcd58df-7bc6-47d7-908d-99796934ffad', '21feff02-016d-46e2-bb9d-c27495133b1b', '127. óra: A számonkérés értékelése', 'A statisztikai feladatok és projektmunkák megbeszélése, értékelése.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "6d10e8b1-f3c0-4789-a0ae-d08293000b1a", "text": "Mi volt a projektmunka és a számonkérés legfőbb tanulsága?", "type": "multiple-choice", "options": [{"id": "f62ea14b-6b1f-4449-9874-1bfebb5100da", "text": "Az adatok pontos rögzítése és a helyes skálázás elengedhetetlen a helyes diagramokhoz", "isCorrect": true}, {"id": "82a2268c-b1b1-4aeb-b6c6-0913bacf9bb5", "text": "A rajzolás nem fontos", "isCorrect": false}, {"id": "2284e8a2-47ac-4d7b-848c-35433d6b69d6", "text": "A számolást el kell hagyni", "isCorrect": false}, {"id": "ecd6b793-49c1-46dc-a9ec-e833845d7b98", "text": "Mindegy a skála", "isCorrect": false}], "timeLimit": 15}, {"id": "e866a546-1062-4c3a-90e7-76169261b6c4", "text": "Az átlag kiszámításánál a darabszámmal való osztást nem szabad elfelejteni.", "type": "true-false", "options": [{"id": "13ab26ff-ed13-4ae0-ab94-42cbe1e90391", "text": "Igaz", "isCorrect": true}, {"id": "75b54879-04a6-41df-b2bc-3827d816d3d8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "80a8a15a-4c3f-4fbe-a132-f70e9773a298", "text": "Mennyi a 12 és 18 számtani közepe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "554171bb-3a78-4f6f-ac91-a569f1ecd46e", "text": "A kördiagram körcikkei összefüggenek a százalékos megoszlással.", "type": "true-false", "options": [{"id": "576b01d5-87c2-4a24-8be8-addb441c378a", "text": "Igaz", "isCorrect": true}, {"id": "e2cb9a65-565f-4fba-aef8-666b738809d4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "948b15bf-90a2-4b31-b971-77a5b5a37a10", "text": "A kísérletek során nyert adatok segítenek megérteni a valószínűségi elveket.", "type": "true-false", "options": [{"id": "f790630c-230e-4155-9d68-13659ab26adb", "text": "Igaz", "isCorrect": true}, {"id": "daf2af55-5a47-48dc-a75b-6e147741324e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e6d54e96-c453-41bf-b743-211b83dbffdb", "text": "Mennyi a 5, 10, 15 átlaga?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "e5165354-2de7-4725-b8b8-9730aad0bb9e", "text": "A csoporteredmények bemutatása fejlesztette a kommunikációs készséget.", "type": "true-false", "options": [{"id": "e6221b74-6e30-46ce-82f0-4775a3d232d9", "text": "Igaz", "isCorrect": true}, {"id": "f039fc75-e101-4228-9f6e-8bc5034339b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4d1b8d18-5e45-4f8d-aa55-8ceb433daddb', '21feff02-016d-46e2-bb9d-c27495133b1b', '128. óra: Mindennapi pénzügyeink I.', 'Alapvető pénzügyi fogalmak: megtakarítás, kamat, kamatláb, futamidő, bankbetét.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "2c8a8c73-155e-4dec-ab8b-d6a205b9afaa", "text": "Mit jelent a banki megtakarítás (betét) után járó ''kamat''?", "type": "multiple-choice", "options": [{"id": "2942a14b-b560-47d1-9d90-980172cbed40", "text": "A bank által a lekötött pénz használatáért fizetett plusz összeg", "isCorrect": true}, {"id": "d257b340-b7cb-4e73-aef0-6cdc9a49ef2f", "text": "A bankkezelési díj", "isCorrect": false}, {"id": "7174641c-fe9b-431b-a31a-bbd7283bd876", "text": "A büntetés", "isCorrect": false}, {"id": "5dcf0a31-7c31-4315-a48a-5ba31797cfa6", "text": "A fizetett adó", "isCorrect": false}], "timeLimit": 15}, {"id": "56ba71f7-749e-41cd-8717-54210994fd80", "text": "Ha 100 000 Ft-ot beteszünk a bankba 5%-os éves kamatra, hány Ft kamatot kapunk 1 év múlva? (100000 * 0,05)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5000"}, {"id": "4af310f6-02a5-4160-9b8c-42b13136bdb9", "text": "Mennyi pénzünk lesz a bankban az 1 év letelte után a 100 000 Ft betét és a 5000 Ft kamat összegeként?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "105000"}, {"id": "c05c4172-ee81-4068-b64b-2c4ddad2986d", "text": "A futamidő az az időtartam, ameddig a pénzünket a bankban lekötjük.", "type": "true-false", "options": [{"id": "9134c2f0-a169-4447-9656-15e9836499c4", "text": "Igaz", "isCorrect": true}, {"id": "0d35604f-c340-4989-985c-50659e0f0320", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c67337c8-e749-4ced-bc86-08688ea23706", "text": "A hitel felvételekor nekünk kell kamatot fizetnünk a banknak a kölcsönzött pénzért.", "type": "true-false", "options": [{"id": "b87aaaa1-1b70-407b-a407-9c3af97634d6", "text": "Igaz", "isCorrect": true}, {"id": "729b8829-094c-4747-8155-255a8f248fcd", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3dda260d-7e98-45b0-b0b0-e83ee57b0a61", "text": "A megtakarítás segít a váratlan kiadások fedezésében és jövőbeli célok megvalósításában.", "type": "true-false", "options": [{"id": "1f87d76a-667b-4dc2-bc83-d9cd827f2f11", "text": "Igaz", "isCorrect": true}, {"id": "0943abb3-f8b5-4b6e-90ed-5493699600c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e4ff2784-d5b7-42b6-ac33-11f63d857b6d", "text": "Mennyi 200 000 Ft 10%-os éves kamata 1 évre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('1ef1a0b2-1b4d-41c5-9bf6-51e0a53173f5', '21feff02-016d-46e2-bb9d-c27495133b1b', '129. óra: Mindennapi pénzügyeink II.', 'Devizák, valutavételi és -eladási árfolyam, valutaváltás.', 'Matematika', '6. osztály', 'Mindennapi pénzügyeink', '[{"id": "cecb8493-76b9-4c9c-b993-cfebfa7756c2", "text": "Mit jelent a valuta és deviza árfolyama?", "type": "multiple-choice", "options": [{"id": "f94446cb-3e83-4e34-b20e-f82e65c0a96b", "text": "Egy külföldi pénznem (pl. Euró, Dollár) ára hazai pénzben (Ft-ban)", "isCorrect": true}, {"id": "651a8176-d0c4-457e-9677-b3d932cd0b0d", "text": "A bankjegy színe", "isCorrect": false}, {"id": "b4e73fa2-31b2-4bcc-b733-bff1f78cddf3", "text": "A pénz súlya", "isCorrect": false}, {"id": "c6f006e2-dad1-4037-b7f7-62af3366a479", "text": "A bank nyitvatartása", "isCorrect": false}], "timeLimit": 15}, {"id": "73335107-3e04-487d-9631-c7e3fffadf9b", "text": "Ha 1 Euró (EUR) eladási árfolyama 400 Ft, hány Ft-ba kerül 50 Euró vásárlása? (50 * 400)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20000"}, {"id": "a64b07bf-d610-415a-8a26-4b726f9fec0f", "text": "Ha 100 Eurót váltunk át Ft-ra 400 Ft/EUR vételi árfolyamon, hány Ft-ot kapunk?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40000"}, {"id": "6dcd50d1-3518-41be-b88b-dc9375d8c9fa", "text": "A bankok eladási árfolyama magasabb, mint a vételi árfolyam (ebből származik a váltási haszon).", "type": "true-false", "options": [{"id": "6b7f93c6-4f55-43cd-8034-752eebcbaf8b", "text": "Igaz", "isCorrect": true}, {"id": "da86bff7-cd12-4122-b84e-f4fb9620a05d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "85010b1e-a254-4c93-9130-9d032a06d18e", "text": "Melyik a közös európai pénznem jele és neve?", "type": "multiple-choice", "options": [{"id": "4b98d01b-74bc-40e3-bce0-1432cbce49e2", "text": "EUR (€) - Euró", "isCorrect": true}, {"id": "028224e8-fa74-4e8c-855d-942fdb98a797", "text": "USD ($) - Dollár", "isCorrect": false}, {"id": "08d54bd6-7baa-4236-b7a7-011ebbfb35cd", "text": "GBP (£) - Font", "isCorrect": false}, {"id": "058da020-4bfd-4a3f-9830-ca6318bf12ec", "text": "HUF (Ft) - Forint", "isCorrect": false}], "timeLimit": 15}, {"id": "ab031071-befb-4f9d-a32d-80dbb0f407f1", "text": "Külföldi utazás előtt érdemes tájékozódni a hivalatos árfolyamokról.", "type": "true-false", "options": [{"id": "89e5455c-092a-48f7-b1ae-8c6bd7ec21cf", "text": "Igaz", "isCorrect": true}, {"id": "c4658f4d-eb99-4743-b7d7-c0c812ef172f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8d169837-33a7-4eb7-8128-4d5254cc57e0", "text": "Hány Ft 10 Dollár (USD), ha 1 USD = 350 Ft?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3500"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('99f8085c-6f47-4a35-bfb8-3c5d7b55231e', '21feff02-016d-46e2-bb9d-c27495133b1b', '130. óra: Az egész számokról tanultak összefoglalása, vegyes feladatok', 'Év végi ismétlés: műveletek egész számokkal, előjelek, abszolút érték, ellentett.', 'Matematika', '6. osztály', 'Év végi ismétlés', '[{"id": "7ad82d47-0d1b-4ef7-8ef3-eee44ae7e179", "text": "Mennyi (-15) + (+25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c6cf7fb0-e7ef-4b4e-acf7-885610f8127b", "text": "Mennyi (-8) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "56"}, {"id": "502c70f7-d3db-478b-8f98-cc3ff9393328", "text": "Mennyi (-63) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "ccbd099e-8a8e-4efe-a4c3-8fc9a9822de3", "text": "Két negatív szám szorzata mindig pozitív.", "type": "true-false", "options": [{"id": "e62d5e9c-1ee4-4fed-b274-bfe1cfa77822", "text": "Igaz", "isCorrect": true}, {"id": "094518c7-e305-410d-a86d-d15ce65bad23", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c246699-744f-4876-9282-7c779d0dfb41", "text": "Mennyi |-40|?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "ec7f125a-3b55-4119-aa24-910f3ce87903", "text": "Melyik szám nagyobb: -12 vagy -4?", "type": "multiple-choice", "options": [{"id": "79671ea3-d75f-4ea6-aa69-dcf65c56bb9c", "text": "-4", "isCorrect": true}, {"id": "950c02a4-6a50-4176-a68d-8cb5ad02aee4", "text": "-12", "isCorrect": false}, {"id": "9c54a098-87ed-438c-8de0-718761f0f0dd", "text": "Egyenlők", "isCorrect": false}, {"id": "a5e5b142-e4c8-49e0-8b60-6cdd05bbd890", "text": "Nem eldönthető", "isCorrect": false}], "timeLimit": 15}, {"id": "b4989db7-b194-43a6-a8ff-69e1d0084edc", "text": "Mennyi (-5) * (-2) * (-3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-30"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;